const EXPATS=[
 {id:"e1",name:"Sofia Ramírez",ini:"SR",lang:"ES",langs:[["ES","Native"],["EN","C1"],["ET","A2"]],area:"Kesklinn",since:"Feb 2026"},
 {id:"e2",name:"Daniel Keller",ini:"DK",lang:"DE",langs:[["DE","Native"],["EN","C1"]],area:"Kalamaja",since:"Sep 2025"},
 {id:"e3",name:"Lina Vaitkutė",ini:"LV",lang:"LT",langs:[["LT","Native"],["EN","B2"],["RU","B1"]],area:"Mustamäe",since:"Jan 2026"},
 {id:"e4",name:"Yuki Tanaka",ini:"YT",lang:"JA",langs:[["JA","Native"],["EN","B2"]],area:"Kadriorg",since:"Aug 2026"},
 {id:"e5",name:"Chloé Dubois",ini:"CD",lang:"FR",langs:[["FR","Native"],["EN","B2"],["ET","A2"]],area:"Kalamaja",since:"Mar 2026"},
 {id:"e6",name:"Marco Pellegrini",ini:"MP",lang:"IT",langs:[["IT","Native"],["EN","C1"],["ES","B2"]],area:"Kesklinn",since:"Oct 2025"},
 {id:"e7",name:"Priya Nair",ini:"PN",lang:"EN",langs:[["EN","Native"],["ET","A2"]],area:"Mustamäe",since:"Jun 2026"},
 {id:"e8",name:"Erik Svensson",ini:"ES",lang:"SV",langs:[["SV","Native"],["EN","C1"],["FI","B1"]],area:"Pirita",since:"Nov 2025"}
];
Object.assign(LNAME,{LT:"Lithuanian",JA:"Japanese",SV:"Swedish"});
const EXTRA_REQ=[["Bathroom tap keeps dripping","Started yesterday, hot water side.",1,"Mon",20,"09:00"],["Check before landlord inspection","Inspection is next week, want everything working.",0,"Thu",22,"11:00"],["Help after a small flood","Washing machine hose came off, floor was wet.",2,"Sat",24,"10:00"],["Quote for a bigger job","Landlord agreed to pay, need a written quote first.",1,"Tue",27,"14:00"],["Urgent, no hot water","Boiler shows an error since this morning.",2,"Mon",13,"16:00"]];
const EXREPLIES_EXTRA={FR:["Parfait, j'accepte. À bientôt !","Perfect, I accept. See you soon!"],IT:["Perfetto, accetto. A presto!","Perfect, I accept. See you soon!"],EN:["Great, accepted. See you then!","Great, accepted. See you then!"],SV:["Toppen, jag accepterar. Vi ses!","Great, I accept. See you!"]};
const REQ_BY_CAT={
 Plumbing:[["Leaking kitchen tap","Dripping for a week, the cupboard under the sink is wet.",2,"Tue","10:00"],["Radiator not heating","Bedroom radiator stays cold, the others work.",1,"Wed","16:00"],["Slow bathroom drain","Shower drains very slowly, tried a plunger.",1,"Thu","12:00"]],
 Electrical:[["Socket not working","Kitchen socket died, the fuse did not trip.",1,"Tue","09:00"],["Install ceiling light","Replace the old fitting in the living room.",2,"Wed","11:00"],["Safety check before moving in","Landlord asked for a certificate.",0,"Thu","09:00"]],
 Painting:[["Paint the living room","Two walls, about 30 m², light grey.",2,"Thu","08:00"],["Patch and paint hallway","Holes from old shelves, same white.",1,"Fri","12:00"],["Bedroom ceiling","Water stain after a leak, needs sealing and paint.",2,"Sat","10:00"]],
 Cleaning:[["Move out clean","2 room flat, keys back Friday.",0,"Thu","09:00"],["Deep clean kitchen","After renovation, dust everywhere.",1,"Fri","13:00"],["Weekly clean","Looking for someone regular, Tuesdays.",0,"Tue","10:00"]],
 Handyman:[["Assemble wardrobe","IKEA PAX, two doors, parts are in the flat.",1,"Wed","14:00"],["Mount a TV","55 inch on a plaster wall.",1,"Thu","16:00"],["Fix bathroom door lock","Does not close properly.",1,"Fri","10:00"]],
 Moving:[["Move a sofa","From Kalamaja to Mustamäe, third floor no lift.",2,"Sat","11:00"],["Flat move","2 rooms, boxes packed, about 20 items.",0,"Sat","09:00"],["IKEA pickup","Order ready at the store, deliver to Kesklinn.",0,"Fri","15:00"]]
};
const pTrade=()=>S.trade||"Plumbing";
const pRate=()=>+(S.rate||38);
const pMat=()=>MAT[pTrade()];
const pName=()=>S.name||"Mart Kask";
const pFirst=()=>pName().split(" ")[0];
const pNative=()=>{const n=Object.entries(S.langs).find(([c,l])=>l==="Native");return n?n[0]:"ET"};
const pSpeaks=ex=>ex.langs.find(([c,l])=>c in S.langs&&(l==="Native"||l>="B2")&&(S.langs[c]==="Native"||S.langs[c]>="B2"));
const PST={new:["New request","rev"],quoted:["Quote sent","rev"],paid:["Booked, paid","ok"],done:["Awaiting confirmation","rev"],released:["Paid out","dark"],disputed:["Problem reported","err"],declined:["Declined","gray"],cancelled:["Cancelled","gray"]};
const ppill=st=>{const [t,k]=PST[st];return `<span class="pill ${k}">${t}</span>`};
const exav=(ex,s=44)=>`<span style="width:${s}px;height:${s}px;border-radius:50%;background:var(--ink);color:#fff;display:inline-flex;align-items:center;justify-content:center;font-family:Sora,sans-serif;font-weight:700;font-size:${Math.round(s*.36)}px;flex-shrink:0">${ex.ini}</span>`;
const ex=id=>EXPATS.find(e=>e.id===id);
const pq=j=>{const labour=S.pricing==="job"?(+S.jobPrice||90):j.hours*pRate();const mat=+j.materials||0;const fee=Math.round((labour+mat)*0.1*100)/100;return{labour,mat,fee,gross:Math.round((labour+mat+fee)*100)/100,net:Math.round((labour+mat)*100)/100}};

function pensure(){
  S.pjobs=S.pjobs||null;S.pchats=S.pchats||{};S.avail=S.avail||null;S.pricing=S.pricing||"hour";S.jobPrice=S.jobPrice||90;S.payouts=S.payouts||[{when:"Mon 6 Oct",amt:412.5},{when:"Mon 29 Sep",amt:268}];
  if(!S.avail){S.avail={};["Mon","Tue","Wed","Thu","Fri"].forEach(d=>S.avail[d]=["09:00","11:00","14:00"]);S.avail.Sat=["10:00"];S.avail.Sun=[]}
  if(!S.pjobs){const reqs=REQ_BY_CAT[pTrade()]||REQ_BY_CAT.Plumbing;const DN={Mon:13,Tue:14,Wed:15,Thu:16,Fri:17,Sat:18,Sun:19};S.pjobs=reqs.map(([t,d,ph,day,slot],i)=>({id:"r"+(i+1),eid:EXPATS[i].id,title:t,desc:d,photos:ph,day,slot,date:DN[day],status:i===2?"paid":"new",hours:1.5,materials:i===2?pMat()[1]:0,matDesc:i===2?pMat()[0]:"",ago:["12 min ago","1 h ago","yesterday"][i],paidAt:i===2?"yesterday":null}));
    S.pjobs.push({id:"r0",eid:"e4",title:"Previous job: "+reqs[1][0].toLowerCase(),desc:reqs[1][1],photos:1,day:"Fri",slot:"10:00",date:9,status:"released",hours:2,materials:pMat()[1],matDesc:pMat()[0],ago:"last week",paidAt:"last week"});
    const extra=[[2,"Fri","09:00","e2","released"],[5,"Mon","14:00","e3","released"],[7,"Wed","11:00","e1","released"],[21,"Wed","09:00","e2","paid"],[23,"Fri","14:00","e4","paid"],[28,"Wed","10:00","e3","paid"],[30,"Fri","09:00","e1","paid"]];
    extra.forEach(([date,day,slot,eid,st],i)=>{const r=reqs[i%reqs.length];S.pjobs.push({id:"x"+i,eid,title:r[0],desc:r[1],photos:r[2],day,slot,date,status:st,hours:[1,1.5,2][i%3],materials:pMat()[1],matDesc:pMat()[0],ago:(st==="released"?"done ":"")+day+" "+date+" Oct",paidAt:st==="released"?"earlier":"last week"})});
    EXTRA_REQ.forEach(([t,d,ph,day,date,slot],i)=>{S.pjobs.push({id:"n"+i,eid:EXPATS[4+(i%4)].id,title:t,desc:d,photos:ph,day,slot,date,status:"new",hours:1.5,materials:0,matDesc:"",ago:["25 min ago","2 h ago","3 h ago","this morning","5 min ago"][i]})});
    S.pjobs.forEach(j=>{if(!S.pchats[j.eid]){const e=ex(j.eid);S.pchats[j.eid]={eid:j.eid,t:Date.now()-Math.random()*1e7,unread:j.status==="new"?1:0,msgs:[{sys:true,text:`Chat with ${e.name.split(" ")[0]} started · translated automatically`},{text:`Hi ${pFirst()}, ${j.title.toLowerCase()}. ${j.desc} Could you come ${j.day} at ${j.slot}?`,orig:`(${LNAME[e.lang]} original)`,when:j.ago,req:j.id}]}}})}
  save();
}
const pchatList=(list,active)=>`<div class="col clist" style="gap:0">${list.map(c=>{const e=ex(c.eid);const lm=c.msgs[c.msgs.length-1];const last={when:lm.when||"",text:lm.text||(lm.quote?"Your quote: "+money(pq(S.pjobs.find(x=>x.id===lm.quote)).gross):"")};return `<button class="row citem ${active===e.id?"on":""}" data-pchat="${e.id}">${exav(e,48)}<span style="flex:1;min-width:0"><span class="row between"><b>${e.name}</b><span class="muted" style="font-size:12px">${last.when||""}</span></span><span class="muted" style="display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;${c.unread?"color:var(--ink);font-weight:700":""}">${esc(last.text)}</span></span>${c.unread?`<span class="nb">${c.unread}</span>`:""}</button>`}).join("")}</div>`;
const pnav=a=>{const n=Object.values(S.pchats).filter(c=>c.unread).length;const nr=S.pjobs.filter(j=>j.status==="new").length;return `<nav class="bnav">${[["phome","home","Home"],["pjobs","calendar","Jobs"],["pchats","chat","Chats"],["pearn","lock","Earnings"],["pme","user","Profile"]].map(([r,i,l])=>`<button data-nav="${r}" class="${a===r?"on":""}"><span class="pil">${ico(i,"#16201D",22)}${r==="pchats"&&n?`<span class="nb">${n}</span>`:""}${r==="pjobs"&&nr?`<span class="nb">${nr}</span>`:""}</span><span>${l}</span></button>`).join("")}</nav>`};
const ptop=()=>`<div class="row between" style="height:48px"><div class="row" style="gap:8px">${mark(28,"#F6F2EA")}<span style="font-family:Sora,sans-serif;font-weight:700;font-size:22px;letter-spacing:-.02em">kodu</span><span class="pill" style="background:var(--mint);color:var(--ink)">Provider</span></div><button class="chip" style="height:40px" data-act="soon" aria-label="Change language">${ico("globe","#16201D",18)} ${pNative()}</button></div>`;
const reqcard=j=>{const e=ex(j.eid);const sp=pSpeaks(e);return `<button class="pc" data-preq="${j.id}" style="gap:10px"><span class="row between" style="width:100%"><b style="font-family:Sora,sans-serif;font-size:17px;text-align:left">${esc(j.title)}</b>${ppill(j.status)}</span><span class="row" style="gap:10px;width:100%">${exav(e,36)}<span class="muted" style="text-align:left;flex:1">${e.name}  ·  ${e.area}<br>${j.day} ${j.slot}  ·  ${sp?`<b style="color:var(--green)">speaks ${LNAME[sp[0]]}</b>`:`<b style="color:var(--green)">translated from ${LNAME[e.lang]}</b>`}</span><span class="muted" style="font-size:12px">${j.ago}</span></span></button>`};

Object.assign(SCREENS,{
phome:()=>{pensure();const news=S.pjobs.filter(j=>j.status==="new");const today=S.pjobs.filter(j=>j.status==="paid");const esc_=S.pjobs.filter(j=>j.status==="paid"||j.status==="done").reduce((a,j)=>a+pq(j).net,0);const month=S.pjobs.filter(j=>j.status==="released").reduce((a,j)=>a+pq(j).net,0)+S.payouts[0].amt;
 return `${ptop()}<div class="col" style="gap:4px"><h2>Tere, ${esc(pFirst())}</h2><p class="sub">${news.length?`${news.length} new ${news.length===1?"request":"requests"} waiting for a quote.`:"No new requests right now."}</p></div>
<div class="row" style="gap:10px">${[[money(esc_),"in escrow"],[money(month),"this month"],[(S.rating||4.9).toFixed(1)+" ★",(S.reviews||127)+" reviews"]].map(([v,l])=>`<div class="card" style="flex:1;padding:12px;text-align:center"><b style="font-family:Sora,sans-serif;font-size:17px;display:block">${v}</b><span class="muted" style="font-size:12px">${l}</span></div>`).join("")}</div>
${S.verified?"":`<div class="note">${ico("shield","#16201D",16)}<span><b>Verification in review.</b> You can quote now; bookings unlock when the ID and licence checks clear, usually within 24 h. <button class="link" data-act="pverify">Prototype: mark as verified</button></span></div>`}
<button class="btn s sm" style="width:100%;height:44px" data-act="pnewreq">Prototype: a new request arrives</button>
<div class="row between" style="font-size:15px"><span class="row" style="gap:8px"><span class="tog ${S.online!==false?"on":""}" style="pointer-events:none"></span>${S.online!==false?"Accepting new requests":"Paused, not visible in search"}</span><button class="link" style="font-size:14px" data-act="togOnline">${S.online!==false?"Pause":"Resume"}</button></div>
${news.length?`${sh("New requests","See all",'data-nav="pjobs"')}<div class="col grid2" style="gap:12px">${news.map(reqcard).join("")}</div>`:""}
${today.length?`${sh("Booked and paid","",'')}<div class="col" style="gap:12px">${today.map(reqcard).join("")}</div>`:""}
<div class="card col"><b style="font-family:Sora,sans-serif;font-size:16px">This week</b><div class="row" style="gap:6px">${DAYS.map(([d,n])=>{const booked=S.pjobs.some(j=>j.status==="paid"&&j.day===d);return `<button class="day ${S.avail[d].length?"":"off"} ${booked?"sel":""}" data-nav="pjobs"><small>${d}</small><b>${n}</b></button>`}).join("")}</div><span class="muted">Dark days have a paid booking. Edit free slots under Jobs.</span></div>
<div style="height:12px"></div>${pnav("phome")}`},

pjobs:()=>{pensure();S.ptab=S.ptab||"Requests";const list={Requests:S.pjobs.filter(j=>j.status==="new"||j.status==="quoted"),Booked:S.pjobs.filter(j=>j.status==="paid"||j.status==="done"),History:S.pjobs.filter(j=>["released","declined","cancelled"].includes(j.status))}[S.ptab]||[];
 return `${ptop()}<h2>Jobs</h2><div class="row" style="gap:0;border-bottom:1px solid var(--line);overflow-x:auto;margin:0 -20px;padding:0 20px">${["Requests","Booked","Calendar","Availability","History"].map(t=>`<button class="link" style="padding:10px 2px;margin-right:16px;font-size:14px;white-space:nowrap;font-weight:${S.ptab===t?700:500};color:${S.ptab===t?"var(--ink)":"var(--muted)"};border-bottom:2.5px solid ${S.ptab===t?"var(--green)":"transparent"};border-radius:0" data-ptab="${t}">${t}</button>`).join("")}</div>
${S.ptab==="Calendar"?pcal():S.ptab==="Availability"?`<p class="sub">Tap a slot to open or close it. Expats only see open slots.</p><div class="col" style="gap:10px">${DAYS.map(([d,n])=>`<div class="card col" style="gap:8px;padding:12px 14px"><div class="row between"><b>${d} ${n} Oct</b><span class="muted">${S.avail[d].length} open</span></div><div class="row wrap" style="gap:6px">${["08:00","09:00","10:00","11:00","12:00","13:00","14:00","15:00","16:00","17:00"].map(t=>{const booked=S.pjobs.some(j=>j.status==="paid"&&j.day===d&&j.slot===t);return `<button class="slot ${S.avail[d].includes(t)?"sel":""}" ${booked?'disabled style="opacity:.5;text-decoration:line-through"':""} data-slot="${d}" data-t="${t}">${t}</button>`}).join("")}</div></div>`).join("")}</div>`
 :list.length?`<div class="col grid2" style="gap:12px">${list.map(reqcard).join("")}</div>`:`<div class="empty"><span class="eic">${ico("calendar","#16201D",30)}</span><b style="font-family:Sora,sans-serif;font-size:18px">Nothing here yet</b><p class="muted">${S.ptab==="Requests"?"New requests from expats land here.":S.ptab==="Booked"?"Paid bookings appear here.":"Completed and declined jobs are kept here."}</p></div>`}
<div style="height:12px"></div>${pnav("pjobs")}`},

preq:()=>{pensure();const j=S.pjobs.find(x=>x.id===S.preqId);const e=ex(j.eid);const sp=pSpeaks(e);const q=pq(j.status==="new"?{...j,materials:j.materials||pMat()[1]}:j);return `${bar()}<div class="row between"><h2 style="font-size:24px">${esc(j.title)}</h2>${ppill(j.status)}</div>
<div class="card row" style="gap:12px">${exav(e)}<span style="flex:1"><b>${e.name}</b><span class="muted" style="display:block">${LNAME[e.lang]} speaking expat  ·  ${e.area}${j.status==="paid"||j.status==="done"?", Narva mnt 7":""}</span><span class="row wrap" style="gap:4px;margin-top:4px">${e.langs.map(([c,l])=>`<span class="lc ${c in S.langs?"on":""}"><b>${c}</b> <span>${l}</span></span>`).join("")}</span></span><button class="btn g sm" style="height:40px" data-pchat="${e.id}">Chat</button></div>
<div class="note">${ico("globe","#16201D",16)}<span>${sp?`You both speak ${LNAME[sp[0]]}.`:`${e.name.split(" ")[0]} writes in ${LNAME[e.lang]}. You read and reply in ${LNAME[pNative()]}, Kodu translates both ways.`}${j.status==="paid"||j.status==="done"||j.status==="released"?" Full address: Narva mnt 7, "+e.area+".":" Address is shared after payment."}</span></div>
<div class="col"><b style="font-family:Sora,sans-serif;font-size:17px">Request</b><p class="sub">${esc(j.desc)}</p><div class="row wrap"><span class="chip">${ico("calendar","#16201D",16)}${j.day} ${j.slot}</span>${j.photos?`<span class="chip">${j.photos} photos</span>`:""}<span class="chip">${j.ago}</span></div>${j.photos?`<div class="row">${Array.from({length:j.photos},()=>`<span class="photo done" style="width:72px;height:72px"></span>`).join("")}</div>`:""}</div>
${j.status==="new"?`<form data-form="quote" class="card col" style="gap:12px"><b style="font-family:Sora,sans-serif;font-size:17px">Your quote</b>
${S.pricing==="job"?`<div class="row between"><span>Fixed price for the job</span><b>€${S.jobPrice}</b></div>`:`<label class="f"><span class="l">Hours on site</span><div class="in"><input name="hours" inputmode="decimal" value="${j.hours}"><span class="muted">h × €${pRate()}</span></div></label>`}
<label class="f"><span class="l">Materials, €</span><div class="in"><input name="materials" inputmode="decimal" value="${j.materials||pMat()[1]}"><span class="muted">€</span></div></label>
<label class="f"><span class="l">What the materials are</span><div class="in"><input name="matDesc" value="${esc(j.matDesc||pMat()[0])}"></div></label>
<label class="f"><span class="l">Note to ${e.name.split(" ")[0]} (translated)</span><textarea class="ta" name="note" placeholder="Write in ${LNAME[pNative()]}">${esc(j.note||"")}</textarea></label>
<div class="col" style="gap:0;border-top:1px solid #EDE8DF;padding-top:8px">${[["You receive",money(q.net),"qn"],["Kodu fee paid by the customer",money(q.fee),"qf"],["Customer pays",money(q.gross),"qg"]].map(([a,b,id],i)=>`<div class="row between" style="padding:6px 0;font-size:${i===2?"16px":"14px"};${i===2?"color:var(--green);font-weight:700":""}"><span>${a}</span><b style="font-family:Sora,sans-serif" id="${id}">${b}</b></div>`).join("")}</div>
${S.declining?`<div class="col" style="gap:8px"><span class="muted" style="font-weight:700">Why are you declining? The customer sees this, translated.</span><div class="row wrap">${["Fully booked that day","Outside my area","Not my type of job","Needs a site visit first"].map(r=>`<button type="button" class="chip" data-dreason="${r}">${r}</button>`).join("")}</div></div>`:""}<div class="row" style="gap:10px"><button class="btn s" type="button" style="width:120px;height:52px" data-act="pdecline">Decline</button><button class="btn p" type="submit" style="height:52px">Send quote</button></div></form>`:""}
${j.status!=="new"?`<div class="card col" style="gap:0;padding:6px 16px">${[[S.pricing==="job"?"Fixed price":"Labour  "+j.hours+" h × €"+pRate(),money(q.labour)],["Materials  "+esc(j.matDesc),money(q.mat)],["Kodu fee, paid by customer",money(q.fee)]].map(([a,b])=>`<div class="row between" style="padding:10px 0;border-bottom:1px solid #EDE8DF;font-size:15px"><span>${a}</span><b style="font-family:Sora,sans-serif">${b}</b></div>`).join("")}<div class="row between" style="padding:12px 0;font-size:17px;color:var(--green)"><b>${j.status==="quoted"?"You receive when done":j.status==="released"?"Paid out":"Held in escrow for you"}</b><b style="font-family:Sora,sans-serif">${money(q.net)}</b></div></div>`:""}
${j.status==="quoted"?`<div class="note">${ico("globe","#16201D",16)}<span>Quote sent and translated. ${e.name.split(" ")[0]} has 24 h to accept. Prototype: the customer accepts in a few seconds.</span></div>`:""}
${j.status==="paid"?`<div class="note">${ico("lock","#16201D",16)}<span>Paid ${j.paidAt}. ${money(q.net)} is released to you when ${e.name.split(" ")[0]} confirms the job, or automatically 72 h after the visit.</span></div>`:""}
${j.status==="done"?`<div class="note">${ico("check","#16201D",16)}<span>You marked this done. Waiting for ${e.name.split(" ")[0]} to confirm. <button class="link" data-act="pconfirm">Prototype: customer confirms</button></span></div>`:""}
<div class="foot">${j.status==="paid"?`<button class="btn p" data-act="pdone">Mark job as done</button><button class="btn s" data-act="pcancel">Cancel booking</button>`:j.status==="quoted"?`<button class="btn s" data-act="pwithdraw">Withdraw quote</button>`:""}</div>`},

pchats:()=>{pensure();const list=Object.values(S.pchats).sort((a,b)=>b.t-a.t);return `${ptop()}<h2>Chats</h2>${pchatList(list)}
<div style="height:12px"></div>${pnav("pchats")}`},

pchat:()=>{pensure();const e=ex(S.pview);const c=S.pchats[e.id];c.unread=0;const j=S.pjobs.find(x=>x.eid===e.id&&x.status!=="released");const list=Object.values(S.pchats).sort((a,b)=>b.t-a.t);
 const msgs=c.msgs.map(m=>m.sys?`<div class="muted center" style="font-size:12px;padding:4px 0">${m.text}</div>`:m.quote?(()=>{const jj=S.pjobs.find(x=>x.id===m.quote);const q=pq(jj);return `<div class="row" style="justify-content:flex-end"><div class="qcard" style="border-radius:18px 18px 4px 18px"><div class="row between"><span style="font-size:13px;font-weight:700;color:var(--green)">Your quote</span>${ppill(jj.status)}</div><b style="font-family:Sora,sans-serif;font-size:22px">${money(q.gross)}</b><span class="muted">${S.pricing==="job"?"fixed price":jj.hours+" h"}, ${esc(jj.matDesc)}, ${jj.day} ${jj.slot}  ·  you receive ${money(q.net)}</span></div></div>`})():`<div class="row" style="justify-content:${m.me?"flex-end":"flex-start"}"><div class="bub2 ${m.me?"me":""}"><span>${esc(m.text)}</span><span class="orig">${ico("globe",m.me?"rgba(255,255,255,.7)":"#56605C",12)} ${m.me?`Delivered in ${LNAME[e.lang]}`:`${e.lang}: ${esc(m.orig)}`}</span></div></div>`).join("")+(c.typing?`<div class="row"><div class="bub2" style="padding:12px 16px"><span class="dots"><i></i><i></i><i></i></span></div></div>`:"");
 return `<div class="chatpage"><aside class="chatside dk"><h2 style="font-size:22px;margin-bottom:8px">Chats</h2>${pchatList(list,e.id)}</aside><div class="chatmain">
<div class="row chathead" style="gap:10px;height:48px"><button class="ib nodk" data-go="back" aria-label="Back">${ico("back")}</button>${exav(e,40)}<span style="flex:1"><b style="display:block">${e.name}</b><span class="muted" style="font-size:12px">${LNAME[e.lang]} speaker  ·  ${e.area}</span></span>${j?`<button class="btn g sm" style="height:36px" data-preq="${j.id}">Job</button>`:""}</div>
<div class="muted center" style="font-size:12px">Translated ${e.lang} ⇄ ${pNative()} automatically</div>
<div class="col msgs" style="gap:10px">${msgs}</div>
<div style="height:12px" class="nodk"></div><div class="qr">${["I can come at the booked time","Please send a photo of the problem","I am on my way","The job is finished"].map(t=>`<button class="chip" data-qr="${t}">${t}</button>`).join("")}</div><form data-form="pmsg" class="cta" style="gap:8px"><button type="button" class="ib" data-act="attach" aria-label="Attach photo">${ico("plus","#16201D",20)}</button><div class="in" style="flex:1;border-radius:22px;height:44px"><input name="msg" placeholder="Write in ${LNAME[pNative()]}…" autocomplete="off"></div><button class="ib" type="submit" style="background:var(--green);border:none" aria-label="Send">${ico("send","#fff",20)}</button></form></div></div><div class="dk">${pnav("pchats")}</div>`},

pearn:()=>{pensure();const inEscrow=S.pjobs.filter(j=>j.status==="paid"||j.status==="done");const pending=S.pjobs.filter(j=>j.status==="quoted");const paid=S.pjobs.filter(j=>j.status==="released");const sum=l=>l.reduce((a,j)=>a+pq(j).net,0);
 return `${ptop()}<h2>Earnings</h2>
<div class="card col" style="background:var(--ink);color:#fff;border:none;gap:4px"><span style="font-size:13px;color:var(--mint);font-weight:700">Next payout  ·  ${S.payout==="Instant payout"?"instant":"Mon 20 Oct"}</span><b style="font-family:Sora,sans-serif;font-size:32px">${money(sum(inEscrow))}</b><span style="font-size:13px;color:rgba(255,255,255,.7)">In escrow across ${inEscrow.length} ${inEscrow.length===1?"job":"jobs"}. Released as customers confirm.</span></div>
<div class="row" style="gap:10px">${[[money(sum(pending)),"quoted, waiting"],[money(sum(paid)+S.payouts.reduce((a,p)=>a+p.amt,0)),"paid out total"]].map(([v,l])=>`<div class="card" style="flex:1;padding:12px;text-align:center"><b style="font-family:Sora,sans-serif;font-size:17px;display:block">${v}</b><span class="muted" style="font-size:12px">${l}</span></div>`).join("")}</div>
<div class="col"><b style="font-family:Sora,sans-serif;font-size:17px">Jobs</b><div class="card" style="padding:4px 16px">${S.pjobs.filter(j=>j.status!=="new"&&j.status!=="declined").map(j=>`<button class="row between" style="width:100%;padding:12px 0;border-bottom:1px solid #EDE8DF;background:none;border-left:none;border-right:none;border-top:none;font:inherit;text-align:left" data-preq="${j.id}"><span><b style="font-size:15px">${esc(j.title)}</b><span class="muted" style="display:block;font-size:12px">${ex(j.eid).name}  ·  ${j.day} ${j.slot}</span></span><span style="text-align:right"><b style="font-family:Sora,sans-serif">${money(pq(j).net)}</b><span style="display:block">${ppill(j.status)}</span></span></button>`).join("")}</div></div>
<div class="col"><b style="font-family:Sora,sans-serif;font-size:17px">Payouts</b><div class="card" style="padding:4px 16px">${S.payouts.map(p=>`<div class="row between" style="padding:12px 0;border-bottom:1px solid #EDE8DF;font-size:15px"><span>${p.when}<span class="muted" style="display:block;font-size:12px">To ${esc((S.iban||"EE38 ···· 5685").slice(0,4))} ···· ${esc((S.iban||"EE38 2200 2210 2014 5685").slice(-4))}</span></span><b style="font-family:Sora,sans-serif">${money(p.amt)}</b></div>`).join("")}</div></div>
<div class="note">${ico("shield","#16201D",16)}<span>Kodu reports annual earnings over €2,000 to the Tax Board (DAC7). Your statement for 2026 arrives in January. <button class="link" data-act="soon">Download statement</button></span></div>
<div style="height:12px"></div>${pnav("pearn")}`},

pme:()=>{pensure();return `${ptop()}<div class="row" style="gap:14px"><span style="width:64px;height:64px;border-radius:32px;background:var(--mint);display:inline-flex;align-items:center;justify-content:center;font-family:Sora,sans-serif;font-weight:700;font-size:22px">${pName().split(" ").map(x=>x[0]).join("").slice(0,2)}</span><span><h2 style="font-size:22px">${esc(pName())}</h2><span class="muted">${esc((S.trade||"Plumbing"))}  ·  ${esc((S.areas||"Kesklinn").split(",")[0])}</span><span class="row wrap" style="gap:6px;margin-top:6px">${S.verified?badge("Verified ID")+(["Plumbing","Electrical"].includes(pTrade())?badge("Licensed"):""):`<span class="pill rev">Verification in review</span>`}</span></span></div>
<div class="card col"><div class="row between"><b>Pricing</b><div class="row" style="gap:6px"><button class="chip ${S.pricing==="hour"?"on":""}" data-pricing="hour">Hourly</button><button class="chip ${S.pricing==="job"?"on":""}" data-pricing="job">Per job</button></div></div>
<form data-form="prate" class="row" style="gap:10px"><label class="f" style="flex:1"><span class="l">${S.pricing==="hour"?"Hourly rate":"Fixed price per job"}</span><div class="in"><input name="price" inputmode="decimal" value="${S.pricing==="hour"?pRate():S.jobPrice}"><span class="muted">€</span></div></label><button class="btn g sm" type="submit" style="height:52px;align-self:flex-end">Save</button></form></div>
<div class="card col"><div class="row between"><b>Languages</b><button class="link" style="font-size:14px" data-go="langs">Edit</button></div><div class="row wrap" style="gap:6px">${Object.entries(S.langs).map(([c,l])=>`<span class="lc on"><b>${c}</b> <span>${l}</span></span>`).join("")}</div><span class="muted">Expats filter on these at B2 or better. Everything else is translated.</span></div>
<div class="card" style="padding:4px 16px">${[["check","Trade and jobs",`${pTrade()}  ·  ${(S.jobs||[]).length||3} job types`,"trade"],["pin","Areas you cover",esc(S.areas||"Kesklinn, Kalamaja"),"trade"],["shield","Verification",(S.verified?"ID and licence verified":"In review, usually 24 h")+(S.vat?"  ·  VAT "+esc(S.vat):""),"verify"],["lock","Payout",`${S.payout||"Weekly payout"}  ·  ${esc((S.iban||"EE38 2200 2210 2014 5685").slice(-4))}`,"payout"],["user","Privacy and data","Download or delete your data",""],["shield","Legal","Provider agreement, terms, privacy","__legal"]].map(([i,t,s,g])=>`<button class="row" style="gap:12px;padding:12px 0;border-bottom:1px solid #EDE8DF;width:100%;background:none;border-left:none;border-right:none;border-top:none;font:inherit;text-align:left" ${g==="__legal"?'data-legal="provider"':g?`data-go="${g}"`:'data-act="soon"'}><span class="eic" style="width:40px;height:40px;border-radius:12px">${ico(i,"#16201D",20)}</span><span style="flex:1"><b style="font-size:16px;font-weight:500">${t}</b><span class="muted" style="display:block">${s}</span></span><span style="display:inline-flex;transform:rotate(180deg)">${ico("back","#56605C",18)}</span></button>`).join("")}</div>
<button class="btn p" data-switch="expat">Switch to the expat app</button><button class="btn s" data-act="pswitch">Preview my profile as an expat sees it</button>
<button class="btn s" data-act="logout">Log out</button><p class="muted center">Kodu prototype  ·  provider v0.1</p>
<div style="height:12px"></div>${pnav("pme")}`}
});

function pcal(){
  const first=3; // 1 Oct 2026 is a Thursday; Monday based grid
  const byDay={};S.pjobs.filter(j=>j.status!=="declined"&&j.status!=="cancelled").forEach(j=>{(byDay[j.date]=byDay[j.date]||[]).push(j)});
  const dot={new:"#F2C14E",quoted:"#F2C14E",paid:"#0E5A4C",done:"#0E5A4C",released:"#16201D"};
  const dname=d=>["Thu","Fri","Sat","Sun","Mon","Tue","Wed"][(d-1)%7];
  const sel=S.calDay;const js=(byDay[sel]||[]).sort((a,b)=>a.slot.localeCompare(b.slot));
  const cells=[];for(let i=0;i<first;i++)cells.push('<span class="cc empty"></span>');
  for(let d=1;d<=31;d++){const n=(byDay[d]||[]).length;cells.push(`<button class="cc ${n?"has":""} ${d===11?"today":""} ${sel===d?"sel":""}" data-cal="${d}" aria-label="${dname(d)} ${d} October, ${n} jobs" ${n?"":"disabled"}><b>${d}</b><span class="dots2">${(byDay[d]||[]).slice(0,3).map(j=>`<i style="background:${dot[j.status]}"></i>`).join("")}</span></button>`)}
  const panel=sel?`<div class="card col" style="gap:8px;background:var(--ivory)"><div class="row between"><b style="font-family:Sora,sans-serif;font-size:16px">${dname(sel)} ${sel} October</b><span class="muted">${js.length} ${js.length===1?"job":"jobs"}</span></div>
    ${js.map(j=>{const e=ex(j.eid);const q=pq(j);const open=S.calJob===j.id;return `<div class="card col" style="gap:8px;padding:10px 12px;${open?"border-color:var(--green)":""}"><button class="row" style="gap:10px;width:100%;background:none;border:none;padding:0;font:inherit;text-align:left" data-caljob="${j.id}">${exav(e,36)}<span style="flex:1;min-width:0"><b style="font-size:15px;display:block">${e.name}</b><span class="muted" style="font-size:13px">${j.slot}  ·  ${esc(j.title)}</span></span><span class="dotc" style="background:${dot[j.status]}"></span><span style="display:inline-flex;transform:rotate(${open?"90deg":"180deg"})">${ico("back","#56605C",18)}</span></button>
      ${open?`<div class="col" style="gap:8px;border-top:1px solid #EDE8DF;padding-top:8px"><span class="muted" style="font-size:13px">${LNAME[e.lang]} speaker  ·  ${e.area}${j.status==="paid"||j.status==="released"?", Narva mnt 7":""}  ·  ${pSpeaks(e)?"you share "+LNAME[pSpeaks(e)[0]]:"translated chat"}</span><p class="sub" style="font-size:14px">${esc(j.desc)}</p><div class="row wrap" style="gap:4px">${ppill(j.status)}<span class="chip" style="height:26px;font-size:12px">${j.day} ${j.slot}</span><span class="chip" style="height:26px;font-size:12px">${S.pricing==="job"?"fixed price":j.hours+" h"}</span>${j.photos?`<span class="chip" style="height:26px;font-size:12px">${j.photos} photos</span>`:""}</div><div class="row between" style="font-size:14px"><span class="muted">${j.status==="new"?"Not quoted yet":j.status==="released"?"Paid out":"You receive"}</span><b style="font-family:Sora,sans-serif;color:var(--green)">${j.status==="new"?"":money(q.net)}</b></div><div class="row" style="gap:8px"><button class="btn p sm" style="flex:1" data-preq="${j.id}">${j.status==="new"?"Open and quote":"Open job"}</button><button class="btn g sm" data-pchat="${e.id}">Chat</button></div></div>`:""}</div>`}).join("")}</div>`:`<p class="muted">Tap a date with dots to see its jobs.</p>`;
  return `<div class="card col" style="gap:10px"><div class="row between"><b style="font-family:Sora,sans-serif;font-size:17px">October 2026</b><span class="row" style="gap:10px;font-size:12px;color:var(--muted)"><span class="row" style="gap:4px"><i class="lg" style="background:#F2C14E"></i>requested</span><span class="row" style="gap:4px"><i class="lg" style="background:#0E5A4C"></i>booked</span><span class="row" style="gap:4px"><i class="lg" style="background:#16201D"></i>paid out</span></span></div>
  <div class="cal"><span class="ch">Mon</span><span class="ch">Tue</span><span class="ch">Wed</span><span class="ch">Thu</span><span class="ch">Fri</span><span class="ch">Sat</span><span class="ch">Sun</span>${cells.join("")}</div></div>
  ${panel}
  <div class="col" style="gap:10px"><b style="font-family:Sora,sans-serif;font-size:17px">Coming up</b>${S.pjobs.filter(j=>j.status==="paid"&&j.date>=11).sort((a,b)=>a.date-b.date).map(j=>{const e=ex(j.eid);return `<button class="pc" data-preq="${j.id}" style="flex-direction:row;align-items:center;gap:12px;padding:12px 14px"><span style="width:44px;text-align:center"><b style="font-family:Sora,sans-serif;font-size:18px;display:block">${j.date}</b><span class="muted" style="font-size:11px">Oct</span></span><span style="flex:1;text-align:left"><b style="font-size:15px">${esc(j.title)}</b><span class="muted" style="display:block;font-size:13px">${e.name}  ·  ${j.slot}</span></span><b style="font-family:Sora,sans-serif;color:var(--green)">${money(pq(j).net)}</b></button>`}).join("")}</div>`;
}
/* scripted customer behaviour */
const EXREPLY={...{},ES:["¡Perfecto, acepto! Hasta el martes.","Perfect, I accept. See you Tuesday."],DE:["Passt, ich nehme das Angebot an. Danke!","That works, I accept the quote. Thanks!"],LT:["Puiku, sutinku. Iki!","Great, I accept. See you!"],JA:["ありがとうございます。お願いします。","Thank you, please go ahead."]};
const EXCHAT=[["Thanks, see you then!","(original)"],["Could you bring a spare cartridge just in case?","(original)"],["Perfect, the door code is 2210.","(original)"]];
function customerActs(eid){const c=S.pchats[eid];const e=ex(eid);const j=S.pjobs.find(x=>x.eid===eid&&x.status==="quoted");c.typing=true;save();if(route==="pchat"&&S.pview===eid)render();
  setTimeout(()=>{c.typing=false;if(j){j.status="paid";j.paidAt="just now";const [o,t]=EXREPLY[e.lang]||EXREPLIES_EXTRA[e.lang]||EXCHAT[0];c.msgs.push({text:t,orig:o,when:"now"});c.msgs.push({sys:true,text:`${e.name.split(" ")[0]} paid ${money(pq(j).gross)} into escrow · address shared`})}else{const [t,o]=EXCHAT[c.msgs.length%EXCHAT.length];c.msgs.push({text:t,orig:o,when:"now"})}
   c.t=Date.now();if(!(route==="pchat"&&S.pview===eid))c.unread=(c.unread||0)+1;save();render();if(j)toast(`${e.name.split(" ")[0]} accepted and paid`)},2200)}

document.addEventListener("click",e=>{
  const cal=e.target.closest("[data-cal]");if(cal){S.calDay=S.calDay===+cal.dataset.cal?null:+cal.dataset.cal;S.calJob=null;save();render();return}
  const cj=e.target.closest("[data-caljob]");if(cj){S.calJob=S.calJob===cj.dataset.caljob?null:cj.dataset.caljob;save();render();return}
  const t=e.target.closest("[data-preq],[data-pchat],[data-ptab],[data-slot],[data-pricing],[data-dreason],[data-act]");if(!t)return;const d=t.dataset;
  if(d.preq){S.preqId=d.preq;S.declining=false;save();go("preq");return}
  if(d.pchat){pensure();S.pview=d.pchat;save();go("pchat");return}
  if(d.ptab){S.ptab=d.ptab;save();render();return}
  if(d.slot&&d.t){const a=S.avail[d.slot];S.avail[d.slot]=a.includes(d.t)?a.filter(x=>x!==d.t):[...a,d.t].sort();save();render();return}
  if(d.pricing){S.pricing=d.pricing;save();render();return}
  const a=d.act;
  if(a==="pnewreq"){pensure();const pool=(REQ_BY_CAT[pTrade()]||REQ_BY_CAT.Plumbing).concat(EXTRA_REQ.map(x=>[x[0],x[1],x[2],x[3],x[5]]));const r=pool[Math.floor(Math.random()*pool.length)];const e=EXPATS[Math.floor(Math.random()*EXPATS.length)];const date=12+Math.floor(Math.random()*18);const day=["Thu","Fri","Sat","Sun","Mon","Tue","Wed"][(date-1)%7];const id="g"+Date.now();
    S.pjobs.unshift({id,eid:e.id,title:r[0],desc:r[1],photos:r[2],day,slot:["09:00","11:00","14:00","16:00"][Math.floor(Math.random()*4)],date,status:"new",hours:1.5,materials:0,matDesc:"",ago:"just now"});
    if(!S.pchats[e.id])S.pchats[e.id]={eid:e.id,t:Date.now(),unread:0,msgs:[{sys:true,text:`Chat with ${e.name.split(" ")[0]} started · translated automatically`}]};const c=S.pchats[e.id];c.msgs.push({text:`Hi ${pFirst()}, ${r[0].toLowerCase()}. ${r[1]} Could you come ${day} ${date} at ${S.pjobs[0].slot}?`,orig:`(${LNAME[e.lang]} original)`,when:"now",req:id});c.unread=(c.unread||0)+1;c.t=Date.now();save();render();toast(`New request from ${e.name.split(" ")[0]}`);return}
  if(a==="pverify"){S.verified=true;save();render();toast("Verified ID and Licensed badges are live");return}
  if(a==="togOnline"){S.online=S.online===false?true:false;save();render();return}
  if(a==="pdecline"){S.declining=true;save();render();return}
  if(d.dreason){const j=S.pjobs.find(x=>x.id===S.preqId);j.status="declined";S.declining=false;const c=S.pchats[j.eid];c.msgs.push({me:true,text:"Sorry, I cannot take this job: "+d.dreason.toLowerCase()+".",orig:"",when:"now"});save();goBack();toast("Declined, the customer was told why");return}
  if(a==="pwithdraw"){const j=S.pjobs.find(x=>x.id===S.preqId);j.status="new";save();render();toast("Quote withdrawn");return}
  if(a==="pdone"){const j=S.pjobs.find(x=>x.id===S.preqId);j.status="done";save();render();toast("Marked as done, customer asked to confirm");return}
  if(a==="pconfirm"){const j=S.pjobs.find(x=>x.id===S.preqId);j.status="released";save();render();toast(money(pq(j).net)+" released to your payout");return}
  if(a==="pcancel"){const j=S.pjobs.find(x=>x.id===S.preqId);if(confirm("Cancel this booking? The customer is refunded in full and your reliability score drops.")){j.status="cancelled";save();render()}return}
  if(a==="pswitch"){S.view="p1";save();go("profile");return}
});
document.addEventListener("submit",e=>{
  const f=e.target;const k=f.dataset.form;if(!["quote","pmsg","prate"].includes(k))return;e.preventDefault();pensure();
  if(k==="quote"){const j=S.pjobs.find(x=>x.id===S.preqId);if(f.hours)j.hours=+f.hours.value||1;j.materials=+f.materials.value||0;j.matDesc=f.matDesc.value.trim()||pMat()[0];j.note=f.note.value.trim();j.status="quoted";
    const c=S.pchats[j.eid];if(j.note)c.msgs.push({me:true,text:j.note,orig:"",when:"now"});c.msgs.push({quote:j.id,when:"now"});c.t=Date.now();save();render();toast("Quote sent and translated");customerActs(j.eid);return}
  if(k==="pmsg"){const v=f.msg.value.trim();if(!v)return;const c=S.pchats[S.pview];c.msgs.push({me:true,text:v,orig:"",when:"now"});c.t=Date.now();save();render();customerActs(S.pview);return}
  if(k==="prate"){const v=+f.price.value;if(!(v>=10&&v<=2000)){toast("Enter a price between €10 and €2000","err");return}if(S.pricing==="hour")S.rate=String(v);else S.jobPrice=v;save();render();toast("Saved");return}
});
/* entry points */
SCREENS.pdone=((orig)=>()=>orig().replace('data-act="soon">Set my availability','data-act="pstart">Set my availability').replace('data-act="soon">Preview my profile','data-act="pswitch">Preview my profile'))(SCREENS.pdone);
document.addEventListener("click",e=>{const t=e.target.closest('[data-act="pstart"]');if(!t)return;pensure();S.ptab="Availability";history=[];go("pjobs")});
if(S.loggedIn&&S.role==="provider"){route="phome";render()}

document.addEventListener("input",ev=>{const f=ev.target.closest("form[data-form=quote]");if(!f)return;const j=S.pjobs.find(x=>x.id===S.preqId);const q=pq({...j,hours:f.hours?(+f.hours.value||0):j.hours,materials:+f.materials.value||0});const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=money(v)};set("qn",q.net);set("qf",q.fee);set("qg",q.gross)});
